from modele import chapitre,E,Q,tableau
from pedagogie import page,bloc

chapitre(15,'droites-cercles','Droites, cercles et constructions','4 · Espace et géométrie',
'Segments · Perpendiculaires · Parallèles · Cercles',
['Employer le vocabulaire et les codes de la géométrie.','Tracer perpendiculaires et parallèles avec les instruments.','Décrire un cercle par la distance au centre.'],
['Règle graduée, équerre et compas.'],[
page(1,'Les mots et les outils de la géométrie',
bloc('definition',r'Par deux points A et B passent : la droite (AB), illimitée des deux côtés ; le segment [AB], limité par A et B ; la demi-droite [AB), qui part de A et traverse B sans s’arrêter. La longueur du segment [AB] se note AB, sans crochets.'),
bloc('savoirfaire',r'Le milieu du segment [AB] est le point du segment situé à égale distance de A et de B. Pour AB $=7$ cm, le milieu est à $3{,}5$ cm de chaque extrémité : règle graduée ou compas permettent de le placer.','Placer un milieu'),
bloc('propriete',r'Sur une figure, des petits traits identiques codent des longueurs égales et un petit carré code un angle droit. Les codes affirment les propriétés : une figure à main levée n’est pas une preuve.'),
bloc('attention',r'La règle sert à tracer et à mesurer, l’équerre contrôle les angles droits, le compas reporte des longueurs et trace les cercles. Vérifier une propriété se fait avec l’instrument adapté.')),
page(2,'Droites particulières et cercles',
bloc('definition',r'Deux droites perpendiculaires se coupent en formant un angle droit : l’équerre le vérifie. Deux droites parallèles ne se coupent jamais : leur écart reste constant, comme les deux bords d’une règle.'),
r'@FIG:cours-cercle@',
bloc('definition',r'Le cercle de centre O et de rayon 3 cm est formé de tous les points situés à exactement 3 cm de O. Le disque contient aussi les points intérieurs, à moins de 3 cm. Un diamètre traverse le cercle en passant par le centre : il mesure deux rayons.'),
bloc('savoirfaire',r'Pour tracer la perpendiculaire à une droite passant par un point : poser un côté de l’angle droit de l’équerre sur la droite, faire glisser jusqu’au point, tracer. Pour une parallèle : équerre tenue sur la droite, règle posée contre l’équerre, faire glisser l’équerre le long de la règle.','Tracer avec l’équerre'))
],[
E('Les bons noms',r'Sur la figure, nommer avec la bonne notation : le segment qui joint A et B ; la droite qui passe par C et D ; la demi-droite qui part de E et passe par F.',r'Le segment $\res{[AB]}$, la droite $\res{(CD)}$ et la demi-droite $\res{[EF)}$. Les crochets enferment les extrémités, les parenthèses laissent la droite filer.','Associer chaque symbole à ce qui est limité ou non.','assert 1==1',figure='geo-1'),
E('Le milieu du segment',r'Le segment [AB] mesure 7 cm. Placer son milieu M et donner la longueur AM.',r'M est sur [AB], à égale distance des extrémités : AM $=7:2=\res{3{,}5}$ cm. Le corrigé montre M et le codage des deux moitiés égales.','Partager la longueur en deux parts égales.','assert Rational(7,2)==Rational("3.5")',figure='geo-2'),
E('Perpendiculaires ?',r'Avec l’équerre, dire quelles paires de droites sont perpendiculaires.',r'L’équerre s’ajuste exactement entre $(d_1)$ et $(d_2)$ : elles sont $\res{\text{perpendiculaires}}$. Les droites $(d_3)$ et $(d_4)$ se coupent sans angle droit : non perpendiculaires. Se couper ne suffit pas.','Tester l’angle droit avec l’équerre, pas à l’œil.','assert 1==1',figure='geo-3'),
E('Parallèles ?',r'Dire si les droites tracées sont parallèles, en contrôlant l’écart avec la règle graduée.',r'L’écart entre $(a)$ et $(b)$ vaut 2 cm aux deux endroits mesurés : elles sont $\res{\text{parallèles}}$. L’écart entre $(a)$ et $(c)$ change : elles finiront par se couper.','Mesurer l’écart à deux endroits éloignés.','assert 2==2',figure='geo-4'),
E('Le vocabulaire du cercle',r'Sur le cercle de centre O, nommer un rayon, un diamètre et une corde tracés sur la figure.',r'$\res{[OA]}$ est un rayon : il joint le centre au cercle. $\res{[BC]}$ est un diamètre : il passe par O. $[DE]$ est une corde : elle joint deux points du cercle sans passer par le centre.','Vérifier le passage par le centre.','assert 1==1',figure='geo-5'),
E('Tracer une perpendiculaire',r'Tracer la droite perpendiculaire à la droite (d) passant par le point A, qui n’est pas sur (d).',r'On pose un côté de l’angle droit de l’équerre sur (d), on glisse jusqu’à A, puis on trace. Le tracé, en vert au corrigé, forme un angle droit codé avec (d).','Garder l’équerre appuyée sur la droite pendant le glissement.','assert 1==1',figure='geo-6'),
E('Tracer une parallèle',r'Tracer la droite parallèle à la droite (d) passant par le point B.',r'On appuie l’équerre sur (d), la règle contre l’équerre, puis on fait glisser l’équerre jusqu’à B avant de tracer. La parallèle, en vert, garde un écart constant avec (d).','Faire glisser l’équerre le long d’une règle fixe.','assert 1==1',figure='geo-7'),
E('Rayon et diamètre',r'Un cercle a un rayon de 4 cm. Quelle est la longueur d’un diamètre ? Et si le diamètre mesure 7 cm, que vaut le rayon ?',r'Un diamètre vaut deux rayons : $4\times2=\res8$ cm. Dans l’autre sens : $7:2=\res{3{,}5}$ cm.','Doubler ou partager en deux.','assert 4*2==8 and Rational(7,2)==Rational("3.5")',figure='geo-8'),
E('Lire les codes',r'La figure porte des codes : petits traits sur [AB] et [AC], carré en A. Que peut-on affirmer sans mesurer ?',r'Les traits identiques affirment $\res{AB=AC}$ ; le petit carré affirme que l’angle en A est $\res{\text{droit}}$. Les codes énoncent les propriétés de la figure, même si le dessin est approximatif.','Faire parler chaque code, rien de plus.','assert 1==1',figure='geo-9'),
E('À 3 cm du puits',r'Sur le plan, O marque un puits. Colorier l’ensemble des points situés à exactement 3 cm de O, puis dire où sont les points à moins de 3 cm.',r'Les points à exactement 3 cm forment le $\res{\text{cercle}}$ de centre O et de rayon 3 cm, tracé en vert. Les points à moins de 3 cm remplissent l’intérieur : c’est le $\res{\text{disque}}$ privé de son bord.','Relier distance au centre et appartenance au cercle.','assert 2*3==6',figure='geo-10'),
E('Un programme à exécuter',r'Exécuter le programme : tracer un rectangle ABCD tel que AB $=5$ cm et BC $=3$ cm ; placer le milieu M de [AB] ; tracer le cercle de centre A passant par M.',r'Le rectangle se construit à l’équerre et à la règle. M est à $5:2=2{,}5$ cm de A ; le cercle de centre A passant par M a donc un rayon de $\res{2{,}5}$ cm. La construction complète figure en vert.','Suivre les étapes dans l’ordre, instrument par instrument.','assert Rational(5,2)==Rational("2.5")',figure='geo-11'),
E('Deux cercles croisés',r'Tracer le segment [AB] avec AB $=4$ cm, puis les cercles de centres A et B, tous deux de rayon 3 cm. Que peut-on dire des points où les cercles se coupent ?',r'Les cercles se coupent en deux points. Chacun est sur les deux cercles : il est à $\res{3\ \mathrm{cm}}$ de A et à $\res{3\ \mathrm{cm}}$ de B. Le compas garantit ces distances sans mesurer.','Relire la définition du cercle pour conclure.','assert 3==3 and 3+3>4',figure='geo-12'),
E('Reproduire sur quadrillage',r'Reproduire la figure sur le quadrillage : un rectangle et une de ses diagonales.',r'On compte les carreaux : 5 vers la droite, 3 vers le haut pour les sommets, puis on joint. La diagonale relie deux sommets opposés. La reproduction figure en vert.','Compter les carreaux pour chaque sommet.','assert 1==1',figure='geo-13'),
E('Perpendiculaires en chaîne',r'Tracer une droite $(d_2)$ perpendiculaire à $(d_1)$, puis une droite $(d_3)$ perpendiculaire à $(d_2)$. Que remarque-t-on pour $(d_1)$ et $(d_3)$ ? Vérifier avec les instruments.',r'$(d_1)$ et $(d_3)$ semblent ne jamais se couper : elles sont $\res{\text{parallèles}}$, l’écart mesuré reste constant. Deux droites perpendiculaires à une même droite sont parallèles entre elles.','Mesurer l’écart entre les deux droites extrêmes.','assert 1==1',figure='geo-14'),
E('Le plan du quartier',r'Sur le plan, la rue des Lilas et la rue des Érables sont tracées, ainsi que l’avenue du Parc.'+Q(r'Citer deux rues parallèles.',r'Citer deux rues perpendiculaires.',r'La fontaine est à égale distance des points F et G marqués sur l’avenue : que peut-on tracer pour la localiser ?'),r'Les rues des Lilas et des Érables gardent le même écart : $\res{\text{parallèles}}$. L’avenue du Parc coupe la rue des Lilas à angle droit codé : $\res{\text{perpendiculaires}}$. La fontaine est sur le cercle de centre F et sur celui de centre G de même rayon : on trace $\res{\text{deux arcs de cercle}}$ qui se croisent.','Lire les codes du plan avant de répondre.','assert 1==1',figure='geo-15')
],reperes=['Notations, codes et instruments','Perpendiculaires et parallèles','Cercle, disque et distances','Programmes de construction'],deco='geometrie')

chapitre(16,'triangles-quadrilateres','Triangles et quadrilatères','4 · Espace et géométrie',
'Figures usuelles · Propriétés · Constructions',
['Reconnaître et nommer les triangles et quadrilatères usuels.','Utiliser leurs propriétés de côtés et d’angles.','Construire ces figures avec règle, équerre et compas.'],
['Perpendiculaires, cercle et report de longueurs.'],[
page(1,'Les triangles',
bloc('definition',r'Un triangle a trois sommets et trois côtés. Le triangle rectangle a un angle droit. Le triangle isocèle a deux côtés de même longueur. Le triangle équilatéral a ses trois côtés de même longueur.'),
r'@FIG:cours-triangles@',
bloc('propriete',r'Dans un triangle isocèle, les deux angles portés par la base sont égaux. Dans un triangle équilatéral, les trois angles sont égaux. Les codes de la figure affirment ces égalités.'),
bloc('attention',r'Un triangle peut cumuler deux natures : rectangle et isocèle à la fois, comme la moitié d’un carré coupé par sa diagonale. Vérifier chaque propriété séparément avec les instruments.')),
page(2,'Construire un triangle',
bloc('savoirfaire',r'Construire un triangle équilatéral de côté 4 cm : tracer [BC] de 4 cm ; ouvrir le compas à 4 cm ; tracer un arc de centre B puis un arc de centre C ; leur croisement donne le troisième sommet A. Le compas reporte les longueurs sans les mesurer.','Construire au compas'),
bloc('exemple',r'Pour un triangle isocèle de base 4 cm et de côtés 6 cm : même méthode, compas ouvert à 6 cm pour les deux arcs. Pour un triangle rectangle : tracer d’abord l’angle droit à l’équerre, puis reporter les deux longueurs sur ses côtés.'),
bloc('propriete',r'L’ordre des étapes compte : d’abord le segment connu, ensuite les arcs, enfin les tracés. Garder les arcs de construction visibles : ils racontent la méthode.'),
bloc('savoirfaire',r'Après la construction, contrôler : mesurer les côtés à la règle, tester l’angle droit à l’équerre. Une construction se vérifie toujours avec les instruments.','Contrôler sa figure')),
page(3,'Les quadrilatères',
bloc('definition',r'Un quadrilatère a quatre côtés. Le rectangle a quatre angles droits ; ses côtés opposés sont parallèles et de même longueur. Le losange a quatre côtés de même longueur. Le carré a quatre angles droits et quatre côtés égaux : il est à la fois rectangle et losange.'),
r'@FIG:cours-quadrilateres@',
bloc('propriete',r'Dans un rectangle, un losange ou un carré, les côtés opposés sont parallèles deux à deux. Le trapèze, le pentagone ou l’hexagone seront précisés plus tard : au CM1, les figures de référence sont le triangle, le carré, le rectangle et le losange.'),
bloc('attention',r'Une figure posée sur la pointe reste ce qu’elle est : un carré incliné est toujours un carré. C’est la liste des propriétés, pas l’orientation du dessin, qui décide du nom.')),
page(4,'Construire des quadrilatères',
bloc('savoirfaire',r'Construire un rectangle de 6 cm sur 4 cm : tracer [AB] de 6 cm ; élever en A et en B des perpendiculaires à l’équerre ; reporter 4 cm sur chacune ; joindre les deux points obtenus. Contrôler le dernier angle à l’équerre.','Le rectangle à l’équerre'),
bloc('exemple',r'Pour un carré de côté $4{,}5$ cm, même méthode avec quatre longueurs égales. Pour un losange de côté 5 cm : tracer [AB], puis depuis A et depuis un point D choisi, reporter 5 cm au compas pour fermer la figure, en gardant les quatre côtés égaux.'),
bloc('savoirfaire',r'Une figure composée se construit étape par étape, en suivant le programme de construction : repérer les points déjà placés, puis les objets qui s’appuient dessus. Relire chaque phrase après son tracé.','Suivre un programme'),
bloc('attention',r'À main levée d’abord : un croquis codé prépare la construction et évite d’oublier une contrainte. Les instruments viennent ensuite pour le tracé exact.'))
],[
E('Reconnaître les triangles',r'Classer les quatre triangles dessinés : rectangle, isocèle, équilatéral ou quelconque.',r'Le triangle 1 porte un petit carré : $\res{\text{rectangle}}$. Le 2 a deux côtés codés égaux : $\res{\text{isocèle}}$. Le 3 a trois côtés codés égaux : $\res{\text{équilatéral}}$. Le 4 n’a aucun code : $\res{\text{quelconque}}$.','Lire les codes avant de juger à l’œil.','assert 1==1',figure='tri-1'),
E('Coder une figure',r'Le triangle MNP vérifie MN $=$ MP $=5$ cm. Recopier la figure et placer les codes qui conviennent. Comment s’appelle ce triangle ?',r'On code [MN] et [MP] avec le même petit trait : le triangle est $\res{\text{isocèle}}$ de sommet principal M. Le corrigé montre les codes en vert.','Coder uniquement ce qui est donné.','assert 5==5',figure='tri-2'),
E('Le triangle équilatéral',r'Construire un triangle équilatéral ABC de côté 4 cm. Laisser les arcs de construction.',r'On trace [BC] de 4 cm, puis deux arcs de rayon 4 cm centrés en B et en C ; leur croisement donne A. Les trois côtés mesurent 4 cm : les arcs du corrigé, en vert, montrent la méthode.','Garder la même ouverture de compas pour les deux arcs.','assert 4==4==4',figure='tri-3'),
E('Reconnaître les quadrilatères',r'Nommer chacun des quatre quadrilatères dessinés, en justifiant avec les codes.',r'Quatre angles droits et côtés opposés égaux : $\res{\text{rectangle}}$. Quatre côtés égaux sans angle droit : $\res{\text{losange}}$. Quatre angles droits et quatre côtés égaux : $\res{\text{carré}}$. Le dernier, sans codes : $\res{\text{quadrilatère quelconque}}$.','Vérifier angles puis côtés.','assert 1==1',figure='tri-4'),
E('Carré ou losange ?',r'La figure montre un quadrilatère aux quatre côtés égaux, posé sur la pointe. Zoé dit : « C’est un carré. » A-t-elle forcément raison ?',r'$\res{\text{Non}}$ : quatre côtés égaux font un losange. Sans angle droit vérifié à l’équerre, rien ne prouve que c’est un carré. Ici, l’équerre ne s’ajuste pas : c’est un losange non carré.','Tester un angle à l’équerre avant de conclure.','assert 1==1',figure='tri-5'),
E('Le triangle rectangle',r'Construire un triangle rectangle en A tel que AB $=5$ cm et AC $=3$ cm. Mesurer BC au millimètre près sur la construction.',r'On trace l’angle droit en A à l’équerre, puis AB $=5$ cm et AC $=3$ cm sur ses côtés, et on joint B à C. Sur une construction soignée, on lit BC $\approx\res{5{,}8\ \mathrm{cm}}$.','Commencer par l’angle droit, finir par l’hypoténuse.','assert 5*5+3*3==34',figure='tri-6'),
E('Le triangle isocèle',r'Construire un triangle isocèle DEF de base EF $=4$ cm et de côtés DE $=$ DF $=6$ cm.',r'On trace [EF] de 4 cm, puis deux arcs de rayon 6 cm centrés en E et en F : leur croisement donne D. Les codes affirment DE $=$ DF $=6$ cm.','Les deux arcs portent la même ouverture de compas.','assert 6==6 and 6+6>4',figure='tri-7'),
E('Le rectangle aux instruments',r'Construire un rectangle ABCD avec AB $=6$ cm et BC $=4$ cm. Contrôler le quatrième angle.',r'Perpendiculaires en A et en B, report de 4 cm, puis jonction. L’équerre confirme le quatrième angle $\res{\text{droit}}$ : la construction est correcte si les trois angles tracés le sont.','Élever les perpendiculaires aux deux bouts du premier côté.','assert 2*(6+4)==20',figure='tri-8'),
E('Le carré penché',r'Construire un carré de côté $4{,}5$ cm dont un côté est déjà tracé en biais sur la feuille.',r'La méthode ne change pas : perpendiculaires aux extrémités du côté donné, report de $4{,}5$ cm, jonction. Le carré reste un carré, $\res{\text{quelle que soit son orientation}}$.','S’appuyer sur le côté donné, pas sur les bords de la feuille.','assert Rational("4.5")*4==18',figure='tri-9'),
E('Le losange au compas',r'Construire un losange ABCD de côté 5 cm, en commençant par l’angle en A dessiné à main levée sur le croquis.',r'Depuis A, reporter 5 cm sur les deux côtés de l’angle : B et D. Puis deux arcs de rayon 5 cm centrés en B et en D donnent C. Les quatre côtés, codés, mesurent $\res5$ cm.','Le compas garde la même ouverture du début à la fin.','assert 5*4==20',figure='tri-10'),
E('Une figure composée',r'Exécuter le programme : construire un rectangle EFGH avec EF $=6$ cm et FG $=3$ cm ; placer le milieu M du segment [EF] ; tracer les segments [MG] et [MH]. Quelle semble être la nature du triangle MGH ?',r'Le rectangle se construit comme à l’exercice 8 ; M est à 3 cm de E. Les segments [MG] et [MH] partagent le rectangle en trois triangles. MG $=$ MH par symétrie de la figure : le triangle MGH est $\res{\text{isocèle}}$.','Placer tous les points nommés avant les derniers tracés.','assert Rational(6,2)==3',figure='tri-11'),
E('Le programme en désordre',r'Remettre dans l’ordre les étapes du programme de construction d’un triangle équilatéral : (a) tracer les arcs ; (b) tracer le segment [BC] de 4 cm ; (c) joindre A à B et à C ; (d) ouvrir le compas à 4 cm.',r'L’ordre correct est $\res{\text{b, d, a, c}}$ : le segment d’abord, le réglage du compas, les arcs qui créent A, puis les côtés. Un programme se lit et s’exécute dans l’ordre.','Chercher ce dont chaque étape a besoin.','assert 1==1',figure='tri-12'),
E('La figure qui ment',r'Un dessin annonce un rectangle, mais l’équerre révèle qu’un angle n’est pas droit. Que peut-on conclure ? Quel nom reste correct pour cette figure ?',r'Un seul angle non droit suffit : ce n’est $\res{\text{pas un rectangle}}$. La figure garde quatre côtés : c’est un $\res{\text{quadrilatère}}$. Une annonce ou une apparence ne remplace pas la vérification.','Confronter l’affirmation aux instruments.','assert 1==1',figure='tri-13'),
E('Le plus grand tour',r'Un carré a des côtés de 6 cm ; un triangle équilatéral a des côtés de 6 cm aussi. Lequel a le plus grand périmètre ?',r'Carré : $4\times6=\res{24}$ cm. Triangle : $3\times6=\res{18}$ cm. Le $\res{\text{carré}}$ a le plus grand tour : il a un côté de plus, de même longueur.','Compter les côtés avant de multiplier.','assert 4*6==24 and 3*6==18 and 24>18',figure='tri-14'),
E('Les diagonales du rectangle',r'Construire un rectangle de 8 cm sur 6 cm, tracer ses deux diagonales, puis les mesurer. Que remarque-t-on ?',r'Les deux diagonales mesurent chacune $\res{10\ \mathrm{cm}}$ : dans un rectangle, les diagonales ont la $\res{\text{même longueur}}$ et se coupent en leur milieu. Cette observation se vérifie à la règle sur toute construction soignée.','Mesurer les deux diagonales avec soin.','assert 6*6+8*8==100 and 10*10==100',figure='tri-15')
],reperes=['Triangles particuliers et codes','Constructions au compas','Quadrilatères usuels et propriétés','Rectangles, carrés et losanges construits'],deco='geometrie')
